from collections import Counter

# Count dialogs per company
company_counts = Counter(d['company_id'] for d in dataset)
print("Total dialogs per company:")
for company, count in company_counts.most_common():
    print(f"  {company}: {count}")

# Let's first do a keyword search to find dialogs related to flight booking issues
booking_keywords = ['booking', 'book', 'reservation', 'reserve', 'booked', 'cancel', 'cancelled', 'rebook', 'reschedule']

print("\n\nDialogs mentioning booking-related keywords per company:")
booking_dialogs = {}
for d in dataset:
    dialog_lower = d['dialog'].lower()
    if any(kw in dialog_lower for kw in booking_keywords):
        company = d['company_id']
        if company not in booking_dialogs:
            booking_dialogs[company] = []
        booking_dialogs[company].append(d)

for company in sorted(booking_dialogs.keys()):
    print(f"  {company}: {len(booking_dialogs[company])}")
